	return toError(fncKgesv(handle, n, nrhs, uintptr(dA), ldda, uintptr(dipiv), uintptr(dB), lddb, uintptr(dX), lddx, uintptr(dWorkspace), lworkBytes, iter, uintptr(dInfo)), "cusolverDnCKgesv")
