	defer slotDsyevdxBufferSize.put(outs)
	if err := toError(fndsyevdxBufferSize(handle, jobz, range_, uplo, n, uintptr(a), lda, vl, vu, il, iu, &outs.out0, uintptr(w), &outs.out1), "cusolverDnDsyevdx_bufferSize"); err != nil {
		return 0, 0, err
	}
